using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Security;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings.IntegrationHealth;
[Authorize(Policy="Permission:"+PermissionCodes.IntegrationsView)]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public IntegrationHealthView Health{get;private set;}=new();public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();var id=current.AccountId.Value;var s=await db.IntegrationSettings.AsNoTracking().SingleOrDefaultAsync(x=>x.AccountId==id&&!x.IsDeleted,ct);Health=new(){SmtpConfigured=s?.EmailSendingEnabled==true&&!string.IsNullOrWhiteSpace(s.SmtpHost)&&!string.IsNullOrWhiteSpace(s.ProtectedSmtpPassword),PublicBaseUrlConfigured=Uri.TryCreate(s?.PublicBaseUrl,UriKind.Absolute,out _),WhatsAppConfigured=!string.IsNullOrWhiteSpace(s?.WhatsAppNumber),ActiveWebhooks=await db.WebhookEndpoints.CountAsync(x=>x.AccountId==id&&x.IsActive&&!x.IsDeleted,ct),FailedWebhooks=await db.WebhookDeliveries.CountAsync(x=>x.AccountId==id&&x.Status==OrcaFacil.Domain.Entities.WebhookDeliveryStatus.Failed&&!x.IsDeleted,ct),ActiveApiKeys=await db.ApiKeys.CountAsync(x=>x.AccountId==id&&x.RevokedAt==null&&!x.IsDeleted,ct),FailedEmails=await db.EmailOutboxMessages.CountAsync(x=>x.AccountId==id&&x.Status==OrcaFacil.Domain.Entities.EmailOutboxStatus.Failed&&!x.IsDeleted,ct),LastImport=await db.DataImports.Where(x=>x.AccountId==id&&!x.IsDeleted).MaxAsync(x=>(DateTime?)x.CreatedAt,ct),LastExport=await db.DataExports.Where(x=>x.AccountId==id&&!x.IsDeleted).MaxAsync(x=>(DateTime?)x.CompletedAt,ct),PendingNotifications=await db.Notifications.CountAsync(x=>!x.IsRead&&!x.IsDeleted&&db.AccountMembers.Any(m=>m.AccountId==id&&m.UserId==x.UserId&&!m.IsDeleted),ct)};return Page();}}public sealed class IntegrationHealthView{public bool SmtpConfigured{get;set;}public bool PublicBaseUrlConfigured{get;set;}public bool WhatsAppConfigured{get;set;}public int ActiveWebhooks{get;set;}public int FailedWebhooks{get;set;}public int ActiveApiKeys{get;set;}public int FailedEmails{get;set;}public DateTime? LastImport{get;set;}public DateTime? LastExport{get;set;}public int PendingNotifications{get;set;}}
